import numpy as np
def equation(eps, T, params):
    c=params[:9]; k=params[9]
    E=[np.ones_like(eps), np.sqrt(eps), eps]
    Tb=[np.ones_like(T), T, np.exp(-k*T)]
    out=0
    for i,e in enumerate(E):
        for j,t in enumerate(Tb):
            out=out+c[3*i+j]*e*t
    return out
